      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher cap and longer notification period, informed by remaining diligence risks."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek a tipping basket, so qualifying losses become recoverable from the first dollar once the threshold is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a higher cap and longer notification period, informed by remaining diligence risks."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Seek fundamental warranty protection up to at least the full purchase price, with a substantially longer claim period"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve remedies for fraud and deliberate concealment, and rights that cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject disclosure by mere reference to other material and blanket public-record disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the constructive-knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective consent and satisfaction of all relevant conditions a Buyer-benefit condition precedent."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require effective releases of relevant security and guarantees at Completion, with controlled arrangements for subsequent registry processing."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate the cost to Seller through payment or an express price deduction, with a true-up or indemnity for uncertainty."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity to cover losses from deficient ownership or rights, third-party claims and reasonable remediation costs, outside general warranty limitations."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a tailored indemnity for the pre-Completion incident, including reasonable investigation, remediation and notification costs and legally recoverable third-party liabilities."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Allocate any pre-Completion or exceptional liabilities appropriately, but do not automatically deduct legitimate future operating expenses merely because they are disclosed."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Define separate regimes for general warranties, fundamental warranties, tax, specific indemnities and contractual payment/performance obligations."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require supporting records, appropriate searches, warranties and completion deliverables."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "The Seller’s statement that tax and IP are “settled” does not establish Buyer agreement."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

